import * as THREE from 'three';

export type Phase = 'ready' | 'playing' | 'paused' | 'won' | 'lost';

export interface HudState {
  hp: number;
  maxHp: number;
  ammo: number;
  magSize: number;
  reserve: number;
  kills: number;
  totalEnemies: number;
  shots: number;
  hits: number;
  reloading: boolean;
  reloadProgress: number;
  x: number;
  z: number;
  yaw: number;
  pitch: number;
  message: string;
  enemyShots: number;
  enemyTracers: number;
  zone: string;
  elapsed: number;
  hitMarker: 'none' | 'body' | 'head';
  damageFlash: number;
  damageDir: number;
}

export const MAG_SIZE = 24;
export const RESERVE_MAX = 168;
export const ENEMY_COUNT = 6;
export const RELOAD_TIME = 1.15;
export const FIRE_INTERVAL = 0.13;
export const PLAYER_RADIUS = 0.42;
export const EYE_HEIGHT = 1.62;
export const ENEMY_HP = 100;
export const BULLET_DAMAGE = 34;
export const HEAD_DAMAGE = 100;

export const SPAWN = new THREE.Vector3(0, 0, 13);

export const ENEMY_SPAWNS: Array<[number, number, string]> = [
  [0, 4, 'A'],
  [-7, -3, 'A'],
  [7.5, -6, 'B'],
  [-2.5, -10, 'B'],
  [4, -14, 'C'],
  [-6, -15, 'C'],
];

export function createInitialHud(): HudState {
  return {
    hp: 100,
    maxHp: 100,
    ammo: MAG_SIZE,
    magSize: MAG_SIZE,
    reserve: RESERVE_MAX,
    kills: 0,
    totalEnemies: ENEMY_COUNT,
    shots: 0,
    hits: 0,
    reloading: false,
    reloadProgress: 0,
    x: SPAWN.x,
    z: SPAWN.z,
    yaw: 0,
    pitch: -0.04,
    message: '',
    enemyShots: 0,
    enemyTracers: 0,
    zone: 'A',
    elapsed: 0,
    hitMarker: 'none',
    damageFlash: 0,
    damageDir: 0,
  };
}

