import type { HudState, Phase } from '../game/engine';

interface Props {
  phase: Phase;
  hud: HudState;
  actions: number;
  bestTime: number | null;
  onStart: () => void;
  onPause: () => void;
  onResume: () => void;
  onRestart: () => void;
  onFire: () => void;
  onReload: () => void;
  onTurn: (dx: number, dy: number) => void;
  onMoveDown: (key: string) => void;
  onMoveUp: (key: string) => void;
}

function fmtTime(t: number) {
  const m = Math.floor(t / 60);
  const s = Math.floor(t % 60);
  return `${m}:${s.toString().padStart(2, '0')}`;
}

export default function GameHud({
  phase, hud, actions, bestTime, onStart, onPause, onResume, onRestart, onFire, onReload, onTurn, onMoveDown, onMoveUp,
}: Props) {
  const playing = phase === 'playing';
  const accuracy = hud.shots > 0 ? Math.round((hud.hits / hud.shots) * 100) : 0;
  const holdProps = (key: string) => ({
    onPointerDown: (e: React.PointerEvent) => { e.preventDefault(); onMoveDown(key); },
    onPointerUp: () => onMoveUp(key),
    onPointerLeave: () => onMoveUp(key),
    onPointerCancel: () => onMoveUp(key),
  });

  return (
    <>
      <div className="hud-top">
        <div className="hp-block">
          <span className="label">生命</span>
          <div className="hp-bar">
            <div className="hp-fill" style={{ width: `${(hud.hp / hud.maxHp) * 100}%`, background: hud.hp > 40 ? 'linear-gradient(90deg,#e15a5a,#6ee7a8)' : '#e15a5a' }} />
          </div>
          <span className="value">{hud.hp}</span>
        </div>
        <div className="kills-block">
          <span className="zone-tag">区域 {hud.zone}</span>
          <span>击杀 {hud.kills}/{hud.totalEnemies}</span>
          <span className="muted">{fmtTime(hud.elapsed)} · 命中率 {accuracy}%</span>
        </div>
      </div>

      <div className="ammo-block">
        <span className={hud.ammo === 0 ? 'empty' : ''}>{hud.ammo}</span>
        <span className="slash">/ {hud.magSize}</span>
        <span className="reserve">| {hud.reserve}</span>
        {hud.reloading && <span className="reload-tip">装填中…</span>}
        {hud.reloading && <div className="reload-bar"><div style={{ width: `${hud.reloadProgress * 100}%` }} /></div>}
      </div>

      {playing && <div className="crosshair"><span /></div>}
      {hud.hitMarker !== 'none' && (
        <div className={`hit-marker ${hud.hitMarker}`}>
          {hud.hitMarker === 'head' ? '✦' : '✕'}
        </div>
      )}
      {hud.damageFlash > 0 && (
        <div className="damage-vignette" style={{ opacity: hud.damageFlash * 0.7 }} />
      )}
      {hud.message && <div className="msg">{hud.message}</div>}

      {playing && (
        <div className="touch-controls">
          <div className="dpad">
            <button data-game-action="primary" className="pad up" {...holdProps('KeyW')} aria-label="前进">▲</button>
            <button className="pad left" {...holdProps('KeyA')} aria-label="左移">◀</button>
            <button className="pad right" {...holdProps('KeyD')} aria-label="右移">▶</button>
            <button className="pad down" {...holdProps('KeyS')} aria-label="后退">▼</button>
          </div>
          <div className="turn-pad">
            <button className="pad" onClick={() => onTurn(0.2, 0)} aria-label="向左看">⟲</button>
            <button className="pad" onClick={() => onTurn(-0.2, 0)} aria-label="向右看">⟳</button>
            <button className="pad" onClick={() => onTurn(0, 0.12)} aria-label="向上看">↑</button>
            <button className="pad" onClick={() => onTurn(0, -0.12)} aria-label="向下看">↓</button>
          </div>
          <div className="action-pad">
            <button className="fire-btn" data-fps-fire onClick={onFire}>射击</button>
            <button className="reload-btn" data-fps-reload onClick={onReload}>换弹</button>
          </div>
        </div>
      )}

      {playing && (
        <button className="pause-btn" data-game-pause onClick={onPause} aria-label="暂停">⏸</button>
      )}

      {(phase === 'ready' || phase === 'paused' || phase === 'won' || phase === 'lost') && (
        <div className="overlay">
          <div className="panel">
            {phase === 'ready' && (
              <>
                <div className="hud-title">仓库突围</div>
                <p className="tagline">冷光行动 · 第一人称</p>
                <p>消灭仓库中全部 {hud.totalEnemies} 名敌人，穿过 A→B→C 三区到达终点。</p>
                <p className="small desktop-controls">鼠标移动转向 · WASD 移动 · Shift 冲刺 · 左键开火 · R 换弹 · Esc 暂停</p>
                <p className="small mobile-controls">方向键移动 · 拖动画面转向 · 点击射击 / 换弹</p>
                <button data-game-start className="primary-btn" onClick={onStart}>开始战斗</button>
              </>
            )}
            {phase === 'paused' && (
              <>
                <div className="hud-title">已暂停</div>
                <p className="small">生命 {hud.hp} · 击杀 {hud.kills}/{hud.totalEnemies} · 动作 {actions}</p>
                <button data-game-resume className="primary-btn" onClick={onResume}>继续</button>
                <button data-game-restart className="ghost-btn" onClick={onRestart}>重开</button>
              </>
            )}
            {phase === 'won' && (
              <>
                <div className="hud-title win">战斗胜利</div>
                <p>击杀 {hud.kills}/{hud.totalEnemies} · 命中率 {accuracy}%</p>
                <p>用时 {fmtTime(hud.elapsed)} · 剩余生命 {hud.hp}</p>
                {bestTime !== null && <p className="small">最佳用时 {fmtTime(bestTime)}</p>}
                <button data-game-restart className="primary-btn" onClick={onRestart}>再来一局</button>
              </>
            )}
            {phase === 'lost' && (
              <>
                <div className="hud-title lose">战斗失败</div>
                <p>击杀 {hud.kills}/{hud.totalEnemies} · 命中率 {accuracy}%</p>
                <p className="small">生命归零，重新集结。</p>
                <button data-game-restart className="primary-btn" onClick={onRestart}>重新开始</button>
              </>
            )}
          </div>
        </div>
      )}
    </>
  );
}

