import { useEffect, useRef, useState } from 'react';
import { FpsGame } from './game/fps';
import { createInitialHud } from './game/engine';
import type { HudState, Phase } from './game/engine';
import GameHud from './components/GameHud';
import './styles.css';

const BEST_KEY = 'warehouse-breakout-best-time';

export default function App() {
  const mountRef = useRef<HTMLDivElement>(null);
  const gameRef = useRef<FpsGame | null>(null);
  const [phase, setPhase] = useState<Phase>('ready');
  const [hud, setHud] = useState<HudState>(createInitialHud);
  const [actions, setActions] = useState(0);
  const [bestTime, setBestTime] = useState<number | null>(null);

  useEffect(() => {
    const storage = window.atoms?.storage;
    if (storage) {
      const raw = storage.get(BEST_KEY);
      if (raw) {
        const n = Number(raw);
        if (Number.isFinite(n) && n > 0) setBestTime(n);
      }
    }
  }, []);

  useEffect(() => {
    if (!mountRef.current) return;
    const game = new FpsGame(mountRef.current);
    gameRef.current = game;
    game.onChange = (s) => {
      setHud(s);
      setPhase(game.phase);
      setActions(game.actions);
      if (game.phase === 'won') {
        const storage = window.atoms?.storage;
        if (storage) {
          const raw = storage.get(BEST_KEY);
          const prev = raw ? Number(raw) : null;
          if (!prev || s.elapsed < prev) {
            storage.set(BEST_KEY, String(Math.round(s.elapsed * 10) / 10));
            storage.flush?.();
            setBestTime(s.elapsed);
          }
        }
      }
    };
    return () => {
      game.dispose();
      gameRef.current = null;
    };
  }, []);

  return (
    <div
      className="game-root"
      data-game-phase={phase}
      data-game-actions={actions}
      data-fps-x={hud.x.toFixed(3)}
      data-fps-z={hud.z.toFixed(3)}
      data-fps-yaw={hud.yaw.toFixed(4)}
      data-fps-shots={hud.shots}
      data-fps-hits={hud.hits}
      data-fps-ammo={hud.ammo}
      data-fps-hp={hud.hp}
      data-fps-enemy-shots={hud.enemyShots}
      data-fps-enemy-tracers={hud.enemyTracers}
    >
      <div className="viewport" ref={mountRef} />
      <GameHud
        phase={phase}
        hud={hud}
        actions={actions}
        bestTime={bestTime}
        onStart={() => gameRef.current?.gameStart()}
        onPause={() => gameRef.current?.gamePause()}
        onResume={() => gameRef.current?.gameResume()}
        onRestart={() => gameRef.current?.gameRestart()}
        onFire={() => gameRef.current?.publicFire()}
        onReload={() => gameRef.current?.publicReload()}
        onTurn={(dx, dy) => gameRef.current?.turn(dx, dy)}
        onMoveDown={(k) => gameRef.current?.setKey(k, true)}
        onMoveUp={(k) => gameRef.current?.setKey(k, false)}
      />
    </div>
  );
}

