.turn-pad { position: absolute; right: 14px; top: 92px; width: 100px; height: 100px; pointer-events: auto; display: grid; grid-template-columns: 1fr 1fr; gap: 4px; }
.turn-pad .pad { position: static; width: 46px; height: 46px; }
.action-pad { position: absolute; right: 16px; bottom: 78px; display: flex; gap: 10px; pointer-events: auto; }
.fire-btn { width: 74px; height: 54px; border-radius: 10px; border: none; background: linear-gradient(180deg, #e64949, #b32626); color: #fff; font-weight: 800; font-size: 16px; cursor: pointer; }
.fire-btn:active { transform: scale(0.96); }
.reload-btn { width: 60px; height: 54px; border-radius: 10px; border: 1px solid rgba(120, 160, 200, 0.5); background: rgba(30, 40, 52, 0.85); color: #cfe0f0; font-size: 14px; cursor: pointer; }

.pause-btn { position: absolute; top: 56px; right: 12px; width: 40px; height: 40px; border-radius: 8px; background: rgba(14, 18, 24, 0.75); color: #cfe0f0; border: 1px solid rgba(120, 160, 200, 0.3); font-size: 16px; cursor: pointer; z-index: 10; }

.overlay { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: rgba(8, 12, 17, 0.74); backdrop-filter: blur(3px); z-index: 20; }
.panel { background: rgba(20, 27, 35, 0.95); border: 1px solid rgba(120, 160, 200, 0.35); border-radius: 14px; padding: 26px 30px; text-align: center; max-width: 360px; box-shadow: 0 18px 40px rgba(0,0,0,0.5); }
.hud-title { font-size: 24px; font-weight: 800; letter-spacing: 2px; margin-bottom: 6px; }
.hud-title.win { color: #6ee7a8; }
.hud-title.lose { color: #ff6b6b; }
.tagline { color: #ffd166; font-size: 12px; letter-spacing: 3px; margin: 0 0 10px; }
.panel p { margin: 6px 0; font-size: 14px; color: #b8c8d8; }
.panel .small { font-size: 12px; color: #8aa0b5; }
.primary-btn { margin-top: 14px; width: 100%; padding: 12px; border: none; border-radius: 9px; background: linear-gradient(180deg, #4f8dda, #2f66b0); color: #fff; font-size: 15px; font-weight: 700; cursor: pointer; }
.primary-btn:active { transform: scale(0.98); }
.ghost-btn { margin-top: 8px; width: 100%; padding: 10px; border: 1px solid rgba(120, 160, 200, 0.45); border-radius: 9px; background: transparent; color: #cfe0f0; font-size: 14px; cursor: pointer; }

@media (max-width: 500px) {
  .hp-bar { width: 80px; }
  .panel { padding: 20px; margin: 0 14px; }
  .ammo-block { bottom: 150px; min-width: 110px; }
  .action-pad { bottom: 84px; }
  .turn-pad { top: 80px; }
}
